import{_ as l,o as t,c as r,ah as i}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"tags":["philosophy/Ethics"],"date":"2026-10-08T00:00:00.000Z"},"headers":[{"level":2,"title":"오늘 강의 개요 (4주차, 온라인 강의)","slug":"오늘-강의-개요-4주차-온라인-강의","link":"#오늘-강의-개요-4주차-온라인-강의","children":[]},{"level":2,"title":"상점주인 사례 — 외적 행위 vs 도덕적 동기","slug":"상점주인-사례-—-외적-행위-vs-도덕적-동기","link":"#상점주인-사례-—-외적-행위-vs-도덕적-동기","children":[]},{"level":2,"title":"칸트를 계몽주의 맥락에 위치시키기","slug":"칸트를-계몽주의-맥락에-위치시키기","link":"#칸트를-계몽주의-맥락에-위치시키기","children":[{"level":3,"title":"뉴턴 과학이라는 모델","slug":"뉴턴-과학이라는-모델","link":"#뉴턴-과학이라는-모델","children":[]},{"level":3,"title":"자연법칙 vs 자유의 법칙","slug":"자연법칙-vs-자유의-법칙","link":"#자연법칙-vs-자유의-법칙","children":[]}]},{"level":2,"title":"『도덕형이상학 정초(Groundwork of the Metaphysics of Morals)』의 기획","slug":"『도덕형이상학-정초-groundwork-of-the-metaphysics-of-morals-』의-기획","link":"#『도덕형이상학-정초-groundwork-of-the-metaphysics-of-morals-』의-기획","children":[]},{"level":2,"title":"선의지(good will) — 유일하게 무조건적으로 선한 것","slug":"선의지-good-will-—-유일하게-무조건적으로-선한-것","link":"#선의지-good-will-—-유일하게-무조건적으로-선한-것","children":[{"level":3,"title":"사고실험 — 아이를 구하려는 두 사람","slug":"사고실험-—-아이를-구하려는-두-사람","link":"#사고실험-—-아이를-구하려는-두-사람","children":[]}]},{"level":2,"title":"세 가지 조건적 선(conditional goods)","slug":"세-가지-조건적-선-conditional-goods","link":"#세-가지-조건적-선-conditional-goods","children":[]},{"level":2,"title":"칸트의 행복 vs 아리스토텔레스의 에우다이모니아","slug":"칸트의-행복-vs-아리스토텔레스의-에우다이모니아","link":"#칸트의-행복-vs-아리스토텔레스의-에우다이모니아","children":[]},{"level":2,"title":"도덕적 운(moral luck) — 선의지와 결과의 관계 정리","slug":"도덕적-운-moral-luck-—-선의지와-결과의-관계-정리","link":"#도덕적-운-moral-luck-—-선의지와-결과의-관계-정리","children":[]}],"relativePath":"philosophy/Ethics/06. 칸트 윤리학 — 도덕적 보편성과 선의지.md","filePath":"philosophy/Ethics/06. 칸트 윤리학 — 도덕적 보편성과 선의지.md"}'),s={name:"philosophy/Ethics/06. 칸트 윤리학 — 도덕적 보편성과 선의지.md"};function n(a,o,e,g,h,u){return t(),r("div",null,[...o[0]||(o[0]=[i('<blockquote><p>📎 <strong>슬라이드 위치</strong>: <code>26-2 Ethics-Week-4-Kants-Moral-Philosophy.pdf</code> 2~14쪽 (아리스토텔레스 복습 ~ 선의지와 결과) + 4주차 온라인 요약 PDF</p></blockquote><h2 id="오늘-강의-개요-4주차-온라인-강의" tabindex="-1">오늘 강의 개요 (4주차, 온라인 강의) <a class="header-anchor" href="#오늘-강의-개요-4주차-온라인-강의" aria-label="Permalink to &quot;오늘 강의 개요 (4주차, 온라인 강의)&quot;">​</a></h2><p>지금까지 <a href="./04. 습관화와 성격의 탁월함(2권 1장), 윤리와 정치.html">아리스토텔레스의 덕윤리</a>를 다뤘다면, 이번 시간은 칸트(Immanuel Kant)의 도덕철학으로 넘어간다. 두 철학의 질문 자체가 다르다.</p><ul><li>아리스토텔레스: <strong>&quot;덕 있는 사람이라면 무엇을 할 것인가?&quot;</strong> — 행복한 삶, 성품, 습관화, 감정, 실천적 지혜 중심.</li><li>칸트: <strong>&quot;나는 어떠한 원리(principle)에 따라 행위하며, 그 원리는 도덕적으로 타당한가?&quot;</strong> — 행위자가 행위할 때 따르는 <strong>원리 자체</strong>로 초점이 이동.</li></ul><h2 id="상점주인-사례-—-외적-행위-vs-도덕적-동기" tabindex="-1">상점주인 사례 — 외적 행위 vs 도덕적 동기 <a class="header-anchor" href="#상점주인-사례-—-외적-행위-vs-도덕적-동기" aria-label="Permalink to &quot;상점주인 사례 — 외적 행위 vs 도덕적 동기&quot;">​</a></h2><ul><li>상점주인이 손님에게 정확한 거스름돈을 준다고 가정하자. 같은 행위라도 그 이유는 여러 가지일 수 있다: <ol><li>속이는 것 자체가 잘못이라고 믿어서 (도덕적 원칙)</li><li>감시카메라에 걸릴까 두려워서 (처벌 회피)</li><li>평판을 지키기 위해서 (평판 관리)</li><li>정직이 장기적으로 이익이 되기 때문에 (계산된 이익)</li></ol></li><li><strong>관찰 가능한 행위(정확한 거스름돈)는 동일</strong>하지만, 칸트는 <strong>동기(motive)가 그 행위의 도덕적 가치를 좌우</strong>한다고 본다.</li><li>이는 앞으로 다룰 <strong>&quot;의무에 합치하는 행위(acting in accordance with duty)&quot; vs &quot;의무로부터의 행위(acting from duty)&quot;</strong>라는 핵심 구별을 예고한다 — 겉으로 올바른 행동과, 그것이 옳다는 이유 자체 때문에 행하는 행동은 다르다.</li></ul><h2 id="칸트를-계몽주의-맥락에-위치시키기" tabindex="-1">칸트를 계몽주의 맥락에 위치시키기 <a class="header-anchor" href="#칸트를-계몽주의-맥락에-위치시키기" aria-label="Permalink to &quot;칸트를 계몽주의 맥락에 위치시키기&quot;">​</a></h2><p>칸트 윤리학은 계몽주의(Enlightenment)의 세 가지 문제의식을 반영한다.</p><ol><li><strong>외적 권위로부터의 독립</strong>: 통치자의 명령, 전통, 종교적 해석 모두 그 자체로 부정의할 수 있으므로, 단지 &quot;외부에서 주어졌다&quot;는 이유만으로는 도덕성의 궁극적 근거가 될 수 없다.</li><li><strong>보편적 이성에 대한 신뢰</strong>: 자의적인 외부 권위와 무관하게, 모든 이성적 행위자가 스스로 인식할 수 있는 원리를 찾는다.</li><li><strong>체계적이고 필연적인 원리 추구</strong>.</li></ol><h3 id="뉴턴-과학이라는-모델" tabindex="-1">뉴턴 과학이라는 모델 <a class="header-anchor" href="#뉴턴-과학이라는-모델" aria-label="Permalink to &quot;뉴턴 과학이라는 모델&quot;">​</a></h3><ul><li>과학혁명(특히 뉴턴 물리학)은 칸트에게 중요한 지적 모델을 제공한다 — 단, <strong>칸트가 윤리를 수학으로 환원하려 한 것은 아니다.</strong> 그는 근대 과학이 보여준 <strong>보편성·필연성·체계적 통일성·이성적 근거</strong>에 상응하는 엄밀성을 도덕철학에도 확보하려 했다.</li><li><strong>경험적 관찰은 &quot;사람들이 실제로 어떻게 행동하는가&quot;는 알려주지만, &quot;어떻게 행동해야 하는가&quot;를 그 자체로 정당화하지 못한다.</strong> 그래서 칸트는 도덕성의 <strong>선험적(a priori) 토대</strong>를 찾는다 — 경험에 앞서, 경험과 무관하게 타당한 원리.</li></ul><h3 id="자연법칙-vs-자유의-법칙" tabindex="-1">자연법칙 vs 자유의 법칙 <a class="header-anchor" href="#자연법칙-vs-자유의-법칙" aria-label="Permalink to &quot;자연법칙 vs 자유의 법칙&quot;">​</a></h3><ul><li><strong>자연법칙</strong>: 필연적 인과관계를 기술(記述)한다 — &quot;~이다.&quot;</li><li><strong>도덕법칙</strong>: 자유로운 이성적 행위자가 어떻게 행위해야 하는지를 규정(規定)한다 — &quot;~해야 한다.&quot;</li><li><strong>칸트적 보편성의 의미</strong>: &quot;대부분의 사람이 그렇게 생각한다&quot;는 통계적 일반성이 아니다. <strong>모순이나 자의적 예외 없이 모든 이성적 행위자에게 적용될 수 있는가</strong>가 핵심 기준이다.</li></ul><h2 id="『도덕형이상학-정초-groundwork-of-the-metaphysics-of-morals-』의-기획" tabindex="-1">『도덕형이상학 정초(Groundwork of the Metaphysics of Morals)』의 기획 <a class="header-anchor" href="#『도덕형이상학-정초-groundwork-of-the-metaphysics-of-morals-』의-기획" aria-label="Permalink to &quot;『도덕형이상학 정초(Groundwork of the Metaphysics of Morals)』의 기획&quot;">​</a></h2><ul><li><strong>Groundwork(정초)</strong>: 개별 실천 규칙들을 나열하는 것이 아니라, <strong>도덕적 권위(authority)의 토대 자체를 확립</strong>하려는 시도.</li><li><strong>Metaphysics(형이상학)</strong>: 여기서는 초자연적 존재에 대한 사변이 아니라, <strong>경험적 관찰만으로는 도출되지 않는 도덕성의 선험적 원리</strong>를 탐구한다는 뜻.</li><li>칸트는 우연적인 사회적 관습이나 개인적 선호에 의존하지 않는, <strong>그 자체로 타당한 원리</strong>를 찾는다.</li></ul><h2 id="선의지-good-will-—-유일하게-무조건적으로-선한-것" tabindex="-1">선의지(good will) — 유일하게 무조건적으로 선한 것 <a class="header-anchor" href="#선의지-good-will-—-유일하게-무조건적으로-선한-것" aria-label="Permalink to &quot;선의지(good will) — 유일하게 무조건적으로 선한 것&quot;">​</a></h2><blockquote><p>&quot;선의지를 제외하고는 그 어떤 것도 아무런 제한 없이 선하다고 할 수 없다.&quot;</p></blockquote><ul><li>지성, 용기, 결단력, 끈기, 부, 건강, 권력, 명예, 행복 — 모두 가치 있을 수 있지만, <strong>잘못된 의지에 의해 사용되면 오히려 해악을 증폭</strong>시킬 수 있다. 그래서 이들은 모두 <strong>조건적으로만 선함(conditionally good)</strong>.</li><li><strong>선의지</strong>는 다르다 — 그것이 좋은 결과를 낳았기 때문에 선한 것이 아니라, <strong>어떠한 원리에 따라 의욕(意欲)하는가 자체 때문에 선하다.</strong> 즉 칸트는 <strong>의지의 질(quality of the will)</strong>을 <strong>행위의 성공(success of the action)</strong>과 구분한다.</li></ul><h3 id="사고실험-—-아이를-구하려는-두-사람" tabindex="-1">사고실험 — 아이를 구하려는 두 사람 <a class="header-anchor" href="#사고실험-—-아이를-구하려는-두-사람" aria-label="Permalink to &quot;사고실험 — 아이를 구하려는 두 사람&quot;">​</a></h3><ul><li><strong>A</strong>: 진정한 도덕적 관심에서 아이를 구하려 했지만, 통제할 수 없는 사정으로 실패.</li><li><strong>B</strong>: 홍보(publicity)를 목적으로 행동했지만, 운 좋게 성공.</li><li>결과만으로 평가하면 B가 더 도덕적으로 보일 수 있지만, 칸트는 이것이 <strong>잘못된 평가</strong>라고 본다 — <strong>도덕적 가치는 행위의 성공 여부가 아니라 의지의 질에 있다.</strong></li></ul><h2 id="세-가지-조건적-선-conditional-goods" tabindex="-1">세 가지 조건적 선(conditional goods) <a class="header-anchor" href="#세-가지-조건적-선-conditional-goods" aria-label="Permalink to &quot;세 가지 조건적 선(conditional goods)&quot;">​</a></h2><p>칸트는 무조건적 선(선의지)과 대비되는 조건적 선을 세 범주로 나눈다.</p><ol><li><strong>정신의 재능(talents of mind)</strong>: 지성, 판단력 등.</li><li><strong>기질의 성질(qualities of temperament)</strong>: 용기, 결단력, 끈기 등.</li><li><strong>운명의 선물(gifts of fortune)</strong>: 부, 권력, 명예, 건강 등.</li></ol><p>이 셋 모두 인간의 <strong>행위 능력(capacity to act)을 증대</strong>시키지만, <strong>그 능력이 어떤 도덕적 방향으로 쓰일지는 결정하지 못한다</strong> — 방향을 결정하는 것은 오직 그것을 이끄는 의지다.</p><h2 id="칸트의-행복-vs-아리스토텔레스의-에우다이모니아" tabindex="-1">칸트의 행복 vs 아리스토텔레스의 에우다이모니아 <a class="header-anchor" href="#칸트의-행복-vs-아리스토텔레스의-에우다이모니아" aria-label="Permalink to &quot;칸트의 행복 vs 아리스토텔레스의 에우다이모니아&quot;">​</a></h2><ul><li>칸트는 <strong>행복 자체를 나쁘다고 보지 않는다.</strong> 그의 주장은: 행복은 욕망·경험·문화·상황에 따라 그 내용이 달라지므로 <strong>도덕성의 무조건적·궁극적 토대가 될 수 없다</strong>는 것.</li><li>아리스토텔레스의 <strong>에우다이모니아</strong>(<a href="./02. 아리스토텔레스와 행복(에우다이모니아).html">02. 아리스토텔레스와 행복(에우다이모니아)</a> 참고)는 한 생애 전체에 걸친 <strong>탁월한 활동을 통한 인간적 번영</strong>을 뜻하는 반면, 칸트의 <strong>행복(happiness)</strong>은 주로 개인이 가진 <strong>경향성(inclination) 전체의 충족</strong>을 뜻한다 — 서로 다른 개념.</li><li><strong>두 철학의 진짜 차이</strong>는 &quot;행복을 긍정하느냐 부정하느냐&quot;가 아니라: <ul><li>아리스토텔레스 → 윤리를 <strong>인간적 번영(flourishing)</strong>에 근거시킴</li><li>칸트 → 도덕적 의무를 <strong>이성적 법칙(rational law)</strong>에 근거시킴</li></ul></li></ul><h2 id="도덕적-운-moral-luck-—-선의지와-결과의-관계-정리" tabindex="-1">도덕적 운(moral luck) — 선의지와 결과의 관계 정리 <a class="header-anchor" href="#도덕적-운-moral-luck-—-선의지와-결과의-관계-정리" aria-label="Permalink to &quot;도덕적 운(moral luck) — 선의지와 결과의 관계 정리&quot;">​</a></h2><ul><li>행위자가 합리적이고 책임 있게 행동했더라도 <strong>외부 상황 때문에 실패</strong>할 수 있다 — 이 실패 자체가 선의지의 도덕적 가치를 없애지는 않는다.</li><li><strong>주의</strong>: 이것이 부주의나 무능력을 정당화하는 논리는 아니다 — 선의지는 관련 정보를 검토하고 적절한 수단을 택할 책임도 포함한다.</li><li>칸트의 핵심 논지는 좁게 말하면: <strong>도덕적 가치는 행위자의 통제를 벗어난 우연적 결과에 전적으로 좌우될 수 없다.</strong></li></ul><hr><p><em>출처: 2026-09-25 윤리학 001분반 4주차 온라인 강의(윤지영 교수) 제공 요약 자료(영문+국문)를 바탕으로 직접 재구성한 정리 노트. 원문 요약 자료는 <a href="./Raw-Transcripts/2026-09-25_week4_online-summary.html">Raw-Transcripts 폴더</a>에 별도 보관.</em></p>',30)])])}const p=l(s,[["render",n]]);export{d as __pageData,p as default};
